script:
:root { color-scheme: light; }
html, body { overflow-x: clip; }
html { background-color: var(--a2318bc6-baac-47e4-b9a5-cf9df64652e0); scroll-padding-top: 96px; scrollbar-color: var(--9f13e83c-a77b-4ea0-88e9-c98642c8dec0) var(--a2318bc6-baac-47e4-b9a5-cf9df64652e0); caret-color: var(--125159f9-7542-4805-8e79-458e22907652); accent-color: var(--125159f9-7542-4805-8e79-458e22907652); }
html:has(.qt) { scroll-padding-top: 160px; }
body { background-color: var(--a2318bc6-baac-47e4-b9a5-cf9df64652e0); color: var(--37e85252-98bd-43fb-b320-ebca7f7b6054); -webkit-font-smoothing: antialiased; font-synthesis: none; }
::selection { background-color: color-mix(in oklab, var(--125159f9-7542-4805-8e79-458e22907652) 30%, transparent); color: var(--37e85252-98bd-43fb-b320-ebca7f7b6054); }
:focus-visible { outline: 2px solid var(--125159f9-7542-4805-8e79-458e22907652); outline-offset: 2px; }
a { text-decoration-thickness: 1px; text-underline-offset: 0.16em; }
time, .q-num { font-variant-numeric: tabular-nums; }
.q-display { text-transform: uppercase; letter-spacing: 0.02em; text-wrap: nowrap; text-rendering: geometricPrecision; }
button:disabled, [aria-disabled="true"] { opacity: 0.45; cursor: not-allowed; }
/* in-page links jump, they never glide (Builder smooths them while one is hovered or focused) */
:root:has(a[href^="#"]:is(:hover, :focus-visible)), :root:has(a[href^="#"]:is(:hover, :focus-visible)) * { scroll-behavior: auto; }
/* short desktop screens: the hero ends at the fold, the ink band starts right under it */
@media (min-width: 1200px) and (max-height: 940px) { section.q-hero { padding-bottom: 48px; } }
@view-transition { navigation: auto; }
.q-nav { top: 0; view-transition-name: site-nav; }
.q-skip:focus-visible { top: 16px; }
.q-on-accent :focus-visible { outline-color: var(--37e85252-98bd-43fb-b320-ebca7f7b6054); }
.q-on-ink :focus-visible { outline-color: var(--8c73f435-9fcb-47b2-83c1-5c5a0cb0aaa7); }

.q-btn { transition: background-color 160ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }
.q-btn-ink:hover { background-color: var(--e6531ab3-2d52-43c6-ad11-8a4a6b7226d6); }
.q-btn-frame:hover, .q-btn-frame[aria-current="page"] { background-color: var(--110fedd0-334d-4e59-9145-8bb2817d4afc); }
.q-btn:active { transform: translateY(1px); }
.q-btn:focus-visible { outline: 2px solid var(--125159f9-7542-4805-8e79-458e22907652); outline-offset: 3px; }
.q-link { transition: color 160ms cubic-bezier(0.16, 1, 0.3, 1), opacity 120ms cubic-bezier(0.16, 1, 0.3, 1); }
.q-link:hover { color: var(--125159f9-7542-4805-8e79-458e22907652); }
.q-link:active { opacity: 0.7; }
.q-link:focus-visible { outline: 2px solid var(--125159f9-7542-4805-8e79-458e22907652); outline-offset: 3px; }

@media (prefers-reduced-motion: reduce) {
	*, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
	::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) { animation: none !important; }
}
@media print {
	*, *::before, *::after { animation: none !important; transition: none !important; }
	.q-nav { position: static; }
}
